using PdfSharp.Pdf;using PdfSharp.Pdf.IO;using ProformaViewer.Models;namespace ProformaViewer.Services;public sealed record ExportResult(int PageCount,IReadOnlyList<string> Errors);public sealed class PdfExportService{public Task<ExportResult> ExportAsync(IEnumerable<ProformaEntry> e,string d,IProgress<int>? p=null)=>Task.Run(()=>Export(e,d,p));static ExportResult Export(IEnumerable<ProformaEntry> src,string dest,IProgress<int>? prog){var es=src.ToList();var errors=new List<string>();using var output=new PdfDocument();var done=0;var total=Math.Max(1,es.Sum(e=>e.Pages.Count));foreach(var e in es){if(!System.IO.File.Exists(e.Path)){errors.Add($"{e.Title}: PDF not found");done+=e.Pages.Count;continue;}try{using var input=PdfReader.Open(e.Path,PdfDocumentOpenMode.Import);foreach(var n in e.Pages){if(n<=input.PageCount)output.AddPage(input.Pages[n-1]);else errors.Add($"{e.Title}: page {n} not found");prog?.Report(++done*100/total);}}catch(Exception ex){errors.Add($"{e.Title}: {ex.Message}");}}var count=output.Pages.Count;if(count==0)throw new InvalidOperationException("No valid pages could be exported.\n"+string.Join("\n",errors));output.Save(dest);return new(count,errors);}}